	_, err = tx.ExecContext(ctx,
		`INSERT INTO audit (charge_id, note) VALUES ($1, 'captured')`, p.ID)
	if err != nil {
		return Charge{}, fmt.Errorf("audit charge %d: %w", p.ID, err)
	}
	return p, tx.Commit()
}

