	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// fakeCharges satisfies Charges with no database and no container.
type fakeCharges struct {
	created []NewCharge
	listed  []string // currency passed to each List call
	charges []Charge // what List returns
}

func (f *fakeCharges) List(_ context.Context, currency string) ([]Charge, error) {
	f.listed = append(f.listed, currency)
	return f.charges, nil
}

func (f *fakeCharges) Create(_ context.Context, in NewCharge) (Charge, error) {
	f.created = append(f.created, in)
	return Charge{ID: 1, Amount: in.Amount, Currency: in.Currency}, nil
}

func (f *fakeCharges) Get(context.Context, int64) (Charge, error) {
	return Charge{}, nil
}

func (f *fakeCharges) Latest(context.Context) (Charge, error) {
	return Charge{}, nil
}

func (f *fakeCharges) Report(context.Context, int) error { return nil }

type noReceipts struct{}

func (noReceipts) SendAsync(context.Context, Charge) {}

func TestNegativeAmountIsRejectedAndNotCreated(t *testing.T) {
	fake := &fakeCharges{}
	h := NewHandlers(fake, noReceipts{})
	req := httptest.NewRequest(http.MethodPost, "/charges",
		strings.NewReader(`{"amount":-5,"currency":"USD"}`))
	rec := httptest.NewRecorder()

	h.create(rec, req)

	if rec.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400", rec.Code)
	}
	if len(fake.created) != 0 {
		t.Fatalf("Create was called %d time(s) for a rejected charge",
			len(fake.created))
	}
}

func TestListWithNoChargesReturnsEmptyArray(t *testing.T) {
	fake := &fakeCharges{} // charges is nil, the worst case for encoding
	h := NewHandlers(fake, noReceipts{})
	req := httptest.NewRequest(http.MethodGet, "/charges", nil)
	rec := httptest.NewRecorder()

	h.list(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	if body := strings.TrimSpace(rec.Body.String()); body != "[]" {
		t.Fatalf("body = %q, want []", body)
	}
	if len(fake.listed) != 1 || fake.listed[0] != "" {
		t.Fatalf("List calls = %q, want one call with no filter", fake.listed)
	}
}

func TestListReturnsChargesAsArray(t *testing.T) {
	fake := &fakeCharges{charges: []Charge{
		{ID: 1, Amount: 100, Currency: "USD", Status: "CAPTURED"},
		{ID: 2, Amount: 200, Currency: "USD", Status: "CAPTURED"},
	}}
	h := NewHandlers(fake, noReceipts{})
	req := httptest.NewRequest(http.MethodGet, "/charges?currency=usd", nil)
	rec := httptest.NewRecorder()

	h.list(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q", ct)
	}
	var got []Charge
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("decode body %q: %v", rec.Body.String(), err)
	}
	if len(got) != 2 || got[0].ID != 1 || got[1].ID != 2 {
		t.Fatalf("got %+v", got)
	}
}

func TestListNormalisesCurrencyToUpperCase(t *testing.T) {
	for _, in := range []string{"usd", "Usd", "USD", "uSd"} {
		fake := &fakeCharges{}
		h := NewHandlers(fake, noReceipts{})
		req := httptest.NewRequest(http.MethodGet, "/charges?currency="+in, nil)
		rec := httptest.NewRecorder()

		h.list(rec, req)

		if rec.Code != http.StatusOK {
			t.Fatalf("%q: status = %d, want 200", in, rec.Code)
		}
		if len(fake.listed) != 1 || fake.listed[0] != "USD" {
			t.Fatalf("%q: List calls = %q, want one call with USD", in, fake.listed)
		}
	}
}

func TestListRejectsBadCurrencyWithoutQuerying(t *testing.T) {
	bad := []string{"us", "usdd", "u$d", "123", "us1", "eür", "u d", "%20%20%20"}
	for _, in := range bad {
		fake := &fakeCharges{}
		h := NewHandlers(fake, noReceipts{})
		req := httptest.NewRequest(http.MethodGet, "/charges?currency="+in, nil)
		rec := httptest.NewRecorder()

		h.list(rec, req)

		if rec.Code != http.StatusBadRequest {
			t.Fatalf("%q: status = %d, want 400", in, rec.Code)
		}
		if len(fake.listed) != 0 {
			t.Fatalf("%q: List was called %d time(s) for a rejected currency",
				in, len(fake.listed))
		}
	}
}

func TestPositiveAmountIsCreated(t *testing.T) {
	fake := &fakeCharges{}
	h := NewHandlers(fake, noReceipts{})
	req := httptest.NewRequest(http.MethodPost, "/charges",
		strings.NewReader(`{"amount":500,"currency":"USD"}`))
	rec := httptest.NewRecorder()

	h.create(rec, req)

	if rec.Code != http.StatusCreated || len(fake.created) != 1 {
		t.Fatalf("status = %d, created = %d", rec.Code, len(fake.created))
	}
}
